import {
	Component,
	Event,
	type EventEmitter,
	Host,
	Prop,
	h,
} from "@stencil/core";
import { addHook, removeHook, sanitize } from "dompurify";
import * as marked from "marked";

function parse(
	sourceText: string,
	parsed: boolean,
	opts?: marked.MarkedOptions,
	skipSanitize?: boolean,
) {
	const purifiedString = skipSanitize ? sourceText : sanitize(sourceText);
	return parsed
		? purifiedString
		: (marked.parse(purifiedString, opts) as string);
}

/**
 * @since 1.1.41
 * @status beta
 *
 */
@Component({
	tag: "hbr-markdown",
	styleUrl: "markdown.scss",
	shadow: true,
})
export class HbrMarkdown {
	baseRef: HTMLElement;
	/** content as markdown string */
	@Prop({ reflect: false }) content: string;

	/** set to true if content is HTML string */
	@Prop({ reflect: true }) parsed: false;

	/** callback function to be called after sanitizeAttributes */
	@Prop() afterSanitizeAttributes: undefined;

	/** set to true if content is already sanitized */
	@Prop() skipSanitize = false;

	/** marked options */
	@Prop() markedOptions: marked.MarkedOptions = {};

	/** Emitted after markdown did render. version: 2.9.12 */
	@Event({ eventName: "hbr-markdown-did-render" }) didRender: EventEmitter;

	componentWillRender() {
		addHook("afterSanitizeAttributes", (node: Node) => {
			if (this.afterSanitizeAttributes) {
				// @ts-ignore
				this.afterSanitizeAttributes(node);
			}
		});
	}

	componentDidRender() {
		removeHook("afterSanitizeAttributes");
		this.didRender.emit({ base: this.baseRef });
	}

	render() {
		return (
			<Host>
				<div
					ref={(ref) => {
						this.baseRef = ref;
					}}
					class="prose"
					part="base"
					innerHTML={
						this.content
							? parse(
									this.content,
									this.parsed,
									this.markedOptions,
									this.skipSanitize,
							  )
							: null
					}
				/>
			</Host>
		);
	}
}
